<?php

declare(strict_types=1);

namespace SugarCraft\Dashboard\Tests\Examples;

use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

/**
 * Every example must import only classes that actually exist.
 *
 * The examples were long generated by a template that hard-coded a single
 * namespace for every component, so dozens of files imported phantom FQNs
 * (Layout\Grid\Whatever) that fatal at first use instead of demoing the API.
 * This guard re-derives the full `use` roster of every example file — brace
 * groups and aliases included — and fails on any name the autoloader cannot
 * resolve, which makes phantom-import drift structurally impossible.
 *
 * Runtime execution stays out of the suite (examples are interactive-ish and
 * slow); import resolution is the failure mode that bit us, and it is cheap.
 */
final class ExampleImportsTest extends TestCase
{
    /** @return array<string, array{0: string}> */
    public static function exampleFiles(): array
    {
        $paths = glob(__DIR__ . '/../../examples/*.php');
        self::assertNotEmpty($paths, 'examples/ directory vanished');

        $cases = [];
        foreach ($paths as $path) {
            $cases[basename($path)] = [basename($path)];
        }

        return $cases;
    }

    #[DataProvider('exampleFiles')]
    public function testEveryImportResolvesToARealClass(string $file): void
    {
        $source = file_get_contents(__DIR__ . '/../../examples/' . $file);
        self::assertIsString($source);

        $unresolved = [];

        // Plain imports: use A\B\C;  /  use A\B\C as X;
        if (preg_match_all('/^use\s+((?:SugarCraft|React|Psr)[A-Za-z0-9\\\\]*)(?:\s+as\s+\w+)?;/m', $source, $m)) {
            foreach ($m[1] as $fqn) {
                if (!class_exists($fqn) && !interface_exists($fqn) && !enum_exists($fqn) && !trait_exists($fqn)) {
                    $unresolved[] = $fqn;
                }
            }
        }

        // Grouped imports: use A\B\{C,D as E,F};
        if (preg_match_all('/^use\s+((?:SugarCraft|React|Psr)[A-Za-z0-9\\\\]*)\\\\\{([^}]+)\};/m', $source, $g)) {
            foreach ($g[1] as $i => $prefix) {
                foreach (explode(',', $g[2][$i]) as $member) {
                    $member = preg_split('/\s+as\s+/i', trim($member))[0];
                    $fqn = $prefix . '\\' . $member;
                    if (!class_exists($fqn) && !interface_exists($fqn) && !enum_exists($fqn) && !trait_exists($fqn)) {
                        $unresolved[] = $fqn;
                    }
                }
            }
        }

        $this->assertSame(
            [],
            array_values(array_unique($unresolved)),
            "examples/{$file} imports classes that do not exist"
        );
    }
}
